CREATE EXTENSION IF NOT EXISTS postgis;

-- 1. Tabel Peta Provinsi 2023 (38 Provinsi)
CREATE TABLE IF NOT EXISTS peta_provinsi2023 (
    ogr_fid integer PRIMARY KEY,
    shape geometry,
    id_provinsi text,
    provinsi text,
    centerlat double precision,
    centerlong double precision,
    idprop_alias text,
    nilai1 integer
);

CREATE INDEX IF NOT EXISTS idx_peta_provinsi2023_shape ON peta_provinsi2023 USING GIST(shape);
CREATE INDEX IF NOT EXISTS idx_peta_provinsi2023_provinsi ON peta_provinsi2023(provinsi);

-- 2. Tabel Peta Kabupaten 2023 (514 Kabupaten/Kota)
CREATE TABLE IF NOT EXISTS peta_kab2023 (
    ogr_fid integer PRIMARY KEY,
    shape geometry,
    id text,
    kode_kab text,
    kode_prov text,
    nama_kab text,
    provinsi text,
    centerlat numeric,
    centerlong numeric,
    idprop_alias text,
    nilaikab1 text
);

CREATE INDEX IF NOT EXISTS idx_peta_kab2023_shape ON peta_kab2023 USING GIST(shape);
CREATE INDEX IF NOT EXISTS idx_peta_kab2023_provinsi ON peta_kab2023(provinsi);
CREATE INDEX IF NOT EXISTS idx_peta_kab2023_nama_kab ON peta_kab2023(nama_kab);
CREATE INDEX IF NOT EXISTS idx_peta_kab2023_kode_kab ON peta_kab2023(kode_kab);

-- Clear existing data if re-running
TRUNCATE TABLE peta_provinsi2023;
TRUNCATE TABLE peta_kab2023;

